/**
 * Everything the switches screen edits.
 *
 * This mirrors the UI model one-to-one; `Default` is the only definition of
 * what a fresh install (or a missing blob) uses.
 */
data class ProtectionState (
    var `isProtectionActive`: kotlin.Boolean
    , 
    var `isAdBlockingEnabled`: kotlin.Boolean
    , 
    var `isAnnoyancesEnabled`: kotlin.Boolean
    , 
    var `isBrowsingSecurityEnabled`: kotlin.Boolean
    , 
    var `isTrackingProtectionEnabled`: kotlin.Boolean
    , 
    var `isDnsProtectionEnabled`: kotlin.Boolean
    , 
    /**
     * Spare one app that keeps retrying a host the lists refuse (see
     * [`crate::smart`]). Opt-in: the cooldown lets a blocked host connect.
     */
    var `isSmartFilteringEnabled`: kotlin.Boolean
    , 
    var `isHttpsFilteringEnabled`: kotlin.Boolean
    , 
    /**
     * Terminate and filter QUIC (HTTP/3) instead of dropping it. Needs HTTPS
     * filtering, because the same certificate and decision layer are used.
     */
    var `filterHttp3`: kotlin.Boolean
    , 
    /**
     * AdGuard's "Block ECH", off by default: strip the `ech` SvcParam from
     * DNS answers so those hosts stay decryptable. With it off an ECH
     * connection is spliced and left unfiltered instead of failing.
     */
    var `isEchBlockingEnabled`: kotlin.Boolean
    , 
    var `isFirewallEnabled`: kotlin.Boolean
    , 
    /**
     * Global rules and per-app overrides each have their own gate. Both
     * default on; a disabled set contributes no restriction.
     */
    var `firewallGlobalRules`: kotlin.Boolean
    , 
    var `firewallCustomRules`: kotlin.Boolean
    , 
    /**
     * Notification master for firewall blocks.
     */
    var `firewallNotifications`: kotlin.Boolean
    , 
    /**
     * Default access for any app that inherits a dimension. `true` allows.
     */
    var `firewallAllowWifi`: kotlin.Boolean
    , 
    var `firewallAllowWifiScreenOff`: kotlin.Boolean
    , 
    var `firewallAllowCellular`: kotlin.Boolean
    , 
    var `firewallAllowCellularScreenOff`: kotlin.Boolean
    , 
    var `firewallAllowRoaming`: kotlin.Boolean
    , 
    var `isEcoBatteryModeEnabled`: kotlin.Boolean
    , 
    var `isStealthModeEnabled`: kotlin.Boolean
    , 
    var `blockQuic`: kotlin.Boolean
    , 
    var `blockDoh`: kotlin.Boolean
    , 
    var `blockDot`: kotlin.Boolean
    , 
    var `filterAutoUpdateHours`: kotlin.UInt
    , 
    var `logAllowedRequests`: kotlin.Boolean
    , 
    var `blockMode`: DnsBlockMode
    , 
    var `stripUtmTracking`: kotlin.Boolean
    , 
    var `blockWebRtcLeaks`: kotlin.Boolean
    , 
    var `disguiseUserAgent`: kotlin.Boolean
    , 
    var `blockThirdPartyCookies`: kotlin.Boolean
    , 
    /**
     * Every cookie, the site's own included: the visitor is forgotten between
     * requests, so a login has to be typed again.
     */
    var `blockAllCookies`: kotlin.Boolean
    , 
    /**
     * `ETag` in and `If-None-Match`/`If-Match` out.
     */
    var `stripEtag`: kotlin.Boolean
    , 
    var `stripThirdPartyAuthorization`: kotlin.Boolean
    , 
    var `hideThirdPartyReferer`: kotlin.Boolean
    , 
    /**
     * `Sec-GPC: 1` and `DNT: 1` on every request.
     */
    var `injectGpcDnt`: kotlin.Boolean
    , 
    var `hideSearchQuery`: kotlin.Boolean
    , 
    var `blockPushApi`: kotlin.Boolean
    , 
    var `blockGeolocationApi`: kotlin.Boolean
    , 
    var `selectedDnsProviderId`: kotlin.String
    , 
    var `httpsSkipHosts`: List<kotlin.String>
    , 
    var `httpsOnlyHosts`: List<kotlin.String>
    , 
    var `httpsOnlyMode`: kotlin.Boolean
    , 
    var `proxy`: ProxyState
    , 
    /**
     * BCP-47 language picked in the app; `System` follows the device.
     */
    var `appLanguage`: AppLanguage
    , 
    var `themeMode`: ThemeMode
    , 
    /**
     * Bring the tunnel back after a reboot (only when it was on).
     */
    var `autoStart`: kotlin.Boolean
    , 
    /**
     * Hide ad placeholders with cosmetic rules. Needs HTTPS filtering.
     */
    var `cosmeticFiltering`: kotlin.Boolean
    , 
    /**
     * Force safe search on the major engines (CNAME rewrites).
     */
    var `safeSearch`: kotlin.Boolean
    , 
    /**
     * Group the request log by domain for the services breakdown. Off by
     * default: it is a `GROUP BY` over the whole window on every statistics
     * refresh, and the labels need the services table read from disk.
     */
    var `showServicesBreakdown`: kotlin.Boolean
    , 
    /**
     * Optional subscription for the services table, fetched with the filter
     * lists. Empty keeps the table this build ships: no extra request.
     */
    var `servicesTableUrl`: kotlin.String
    , 
    /**
     * Verbosity of the core's own diagnostics ring, drained to logcat.
     */
    var `logLevel`: LogLevel
    
){
    

    

    
    companion object
}

